// Generated by vibelang from src/workspaces/files/watcher.ts; the migrate flow writes it again with each batch.
export function invalidateFromWatcher(event, ops) {
    const path = ops.normalize(event.data.file);
    if (!path)
        return;
    if (path.startsWith(".git/"))
        return;
    if (ops.hasFile(path) || ops.isOpen?.(path)) {
        ops.loadFile(path);
    }
    if (event.data.event === "change") {
        if (ops.node(path)?.type !== "directory")
            return;
        if (!ops.isDirLoaded(path))
            return;
        ops.refreshDir(path);
        return;
    }
    const parent = path.split("/").slice(0, -1).join("/");
    if (!ops.isDirLoaded(parent))
        return;
    ops.refreshDir(parent);
}
